insert into public.routes (id, name, name_en, region, region_en, travel_mode, length_km, color, description_vi, description_en, geom, bbox, sort, is_active) values
  ('ta-nang-phan-dung', 'Tà Năng – Phan Dũng (trekking)', 'Ta Nang – Phan Dung trek', 'Lâm Đồng', 'Lâm Đồng', 'hiking', 32.4, '#0F766E', 'Cung trekking băng qua các đồi cỏ và rừng thông từ Tà Năng xuống Phan Dũng (nay thuộc tỉnh Lâm Đồng). Phần lớn cung đường mất sóng, chỉ có sóng yếu trên các đỉnh đồi; nơi xảy ra vụ việc tháng 5/2018.', 'Trek across grass hills and pine forest from Ta Nang down to Phan Dung (now Lam Dong province). Most of the trail has no signal, only weak coverage on ridge tops; site of the May 2018 incident.', ST_GeogFromText('SRID=4326;LINESTRING(108.46579 11.59132, 108.46629 11.59155, 108.46623 11.59240, 108.46739 11.59299, 108.47018 11.59279, 108.47201 11.59140, 108.47310 11.58936, 108.47472 11.58814, 108.47502 11.58727, 108.47442 11.58549, 108.47532 11.58310, 108.47487 11.58152, 108.47513 11.57984, 108.47441 11.57925, 108.47254 11.57868, 108.47310 11.57558, 108.47385 11.57544, 108.47510 11.57638, 108.47626 11.57608, 108.47672 11.57546, 108.47830 11.57540, 108.47895 11.57444, 108.48005 11.57452, 108.48142 11.57299, 108.48238 11.57283, 108.48398 11.57354, 108.48690 11.57229, 108.48788 11.57043, 108.48743 11.56850, 108.48884 11.56625, 108.49122 11.56406, 108.49313 11.56162, 108.49504 11.56067, 108.49541 11.55914, 108.49994 11.55635, 108.50260 11.55490, 108.50346 11.55339, 108.50559 11.55248, 108.50769 11.55102, 108.50971 11.55102, 108.51397 11.55009, 108.51962 11.55149, 108.52242 11.55416, 108.52505 11.55423, 108.52511 11.55338, 108.52340 11.55131, 108.52427 11.54907, 108.52425 11.54725, 108.52567 11.54758, 108.52691 11.54734, 108.52948 11.54429, 108.53093 11.54361, 108.52967 11.54272, 108.52908 11.54104, 108.52878 11.53890, 108.52960 11.53740, 108.52868 11.53622, 108.52894 11.53529, 108.52975 11.53479, 108.53005 11.53506, 108.53238 11.53491, 108.53630 11.53379, 108.53921 11.53414, 108.53980 11.53275, 108.53949 11.53110, 108.54059 11.52818, 108.54177 11.52776, 108.54252 11.52638, 108.54412 11.52666, 108.54852 11.52401, 108.54932 11.52335, 108.5